
.card {
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 2px solid var(--c-primary);
  border-radius: 12px;
  overflow: hidden;
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 12px;
  box-shadow: 0 3px 12px rgba(58, 47, 58, 0.12);
}

.header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 10px 14px;
  background: linear-gradient(135deg, var(--c-primary-deep), var(--c-primary));
}

.title {
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 3px;
}

.subtitle {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
}

.body {
  padding: 10px 14px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.section-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--c-primary-deep);
  letter-spacing: 1px;
}

.track {
  position: relative;
  height: 18px;
  border-radius: 9px;
  background: #fff;
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.fill {
  height: 100%;
  transition: width 0.5s ease;
}

.fill-dark {
  background: linear-gradient(90deg, var(--c-primary), var(--c-surface-deep));
}

.fill-danger {
  background: linear-gradient(90deg, var(--c-accent), var(--c-danger));
}

.fill-accent {
  background: linear-gradient(90deg, var(--c-accent), #f0c8cf);
}

.pct {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 10px;
  font-weight: 700;
  color: var(--c-text);
}

.note {
  font-size: 11px;
  color: var(--c-text-muted);
}

.row {
  display: flex;
  flex-direction: row;
  gap: 8px;
}

.mini {
  flex: 1;
  background: #fff;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.mini-label {
  font-size: 10px;
  color: var(--c-text-muted);
}

.mini-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--c-text);
}

.marks {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.mark {
  background: #fff;
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 11px;
  color: var(--c-text);
}

.events {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.event {
  font-size: 11px;
  color: var(--c-text);
  line-height: 1.5;
}

.event.empty {
  color: var(--c-text-muted);
}
